/* One green accent on a paper-white ground, mono for every figure, one spacing scale: a 1280px shell, a
   two-column lede and a table on the board, a plan-and-rail pair on a protocol's page. No framework. */
:root { --canvas: #f3f6f4; --surface: #ffffff; --ink: #121a15; --muted: #5c6a62; --faint: #8c9a92; --border: #dbe4de; --line: #e9f0eb; --accent: #0d6b4f; --accent-soft: #e7f2ec; --negative: #a3362a; --radius: 12px; --font-body: "Noto Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; --font-num: ui-monospace, "SF Mono", Menlo, Consolas, monospace; }* { box-sizing: border-box; }html { color-scheme: light; }body { margin: 0; background: var(--canvas); color: var(--ink); font: 400 15px/1.5 var(--font-body); -webkit-font-smoothing: antialiased; }h1, h2, h3 { margin: 0; font-weight: 600; letter-spacing: -0.02em; text-wrap: balance; }p { margin: 0; }button, input, select { font: inherit; color: inherit; }button { cursor: pointer; }.skip { position: absolute; left: -9999px; padding: 8px 16px; background: var(--surface); z-index: 10; }.skip:focus { left: 24px; top: 24px; }:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }.shell { max-width: 1280px; margin: 0 auto; padding: 18px 40px 48px; }.top { display: flex; align-items: center; justify-content: space-between; gap: 24px; padding-bottom: 13px; border-bottom: 1px solid var(--border); }.brand { display: flex; align-items: baseline; gap: 10px; }.mark { width: 9px; height: 9px; border-radius: 50%; background: var(--accent); align-self: center; }.brand-name { font-family: var(--font-num); font-size: 12.5px; letter-spacing: 0.04em; color: var(--ink); text-transform: uppercase; }.brand-sub { font-size: 12px; color: var(--faint); }.top-right { display: flex; align-items: center; gap: 18px; }.nav { display: flex; gap: 2px; }.nav-link { border: 0; background: none; padding: 4px 9px; font-size: 12.5px; color: var(--muted); border-radius: 6px; }.nav-link:hover { color: var(--ink); }.nav-link.on { color: var(--ink); background: var(--accent-soft); font-weight: 500; }.top-meta { font-family: var(--font-num); font-size: 11.5px; color: var(--faint); white-space: nowrap; }.lede { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 40px; padding: 30px 0 24px; }.lede-copy h1 { font-size: 34px; line-height: 1.12; max-width: 30ch; }.lede-text { margin-top: 10px; color: var(--muted); font-size: 14px; line-height: 1.55; max-width: 62ch; }.facts { margin: 0; display: grid; gap: 7px; align-content: start; padding-left: 28px; border-left: 1px solid var(--border); }.fact { display: flex; align-items: baseline; justify-content: space-between; gap: 14px; }.fact dt { color: var(--muted); font-size: 12px; }.fact dd { margin: 0; font-family: var(--font-num); font-size: 12.5px; font-variant-numeric: tabular-nums; }.controls { display: flex; flex-wrap: wrap; align-items: end; gap: 14px; padding: 14px 0; border-top: 1px solid var(--border); }.field { display: grid; gap: 4px; }.field-label { font-size: 10.5px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--faint); }.field input, .field select { height: 34px; padding: 0 10px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); color: var(--ink); font-size: 13px; min-width: 168px; }.field input { min-width: 236px; }.field input:focus, .field select:focus { outline: none; border-color: var(--accent); }.seg { display: flex; padding: 2px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); }.seg button { height: 28px; padding: 0 10px; border: 0; border-radius: 6px; background: transparent; color: var(--muted); font-size: 12.5px; white-space: nowrap; }.seg button:hover { color: var(--ink); }.seg button[aria-pressed="true"] { background: var(--ink); color: var(--surface); }.count { margin-left: auto; align-self: center; font-family: var(--font-num); font-size: 11.5px; color: var(--faint); white-space: nowrap; }.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; }.table-wrap { overflow-x: auto; }table { width: 100%; border-collapse: collapse; font-size: 13.5px; }.caption { caption-side: top; text-align: left; padding: 10px 16px 8px; color: var(--faint); font-size: 11.5px; border-bottom: 1px solid var(--line); }th, td { padding: 8px 14px; text-align: left; vertical-align: middle; border-bottom: 1px solid var(--line); }th { font-size: 10.5px; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; color: var(--faint); white-space: nowrap; background: var(--surface); }th button { border: 0; background: none; padding: 0; color: inherit; font: inherit; letter-spacing: inherit; text-transform: inherit; }th button:hover { color: var(--ink); }.sort-mark { margin-left: 4px; color: var(--accent); }tbody tr { cursor: pointer; }tbody tr:hover { background: #f7faf8; }tbody tr:last-child td { border-bottom: 0; }tbody tr.static { cursor: default; }tbody tr.static:hover { background: none; }.num { font-family: var(--font-num); font-variant-numeric: tabular-nums; white-space: nowrap; }.sub { color: var(--muted); font-size: 12px; }.pos { color: var(--accent); }.neg { color: var(--negative); }.cell-rank { width: 62px; }.cell-name b { display: block; font-size: 14px; font-weight: 600; letter-spacing: -0.01em; line-height: 1.3; }.cell-name .sub { display: block; margin-top: 1px; line-height: 1.3; }.cell-implied { width: 240px; }.cell-plan { width: 74px; text-align: right; }.rank { display: inline-flex; align-items: center; justify-content: center; width: 25px; height: 25px; border-radius: 50%; font-family: var(--font-num); font-size: 11.5px; border: 1px solid var(--line); color: var(--muted); }.rank.top3 { background: var(--accent); border-color: var(--accent); color: #fff; }.rank.top10 { border-color: #b9cfc3; color: var(--accent); }.rank.live { border: 0; color: var(--faint); }.pill { display: inline-flex; align-items: center; padding: 2px 7px; border-radius: 999px; font-size: 10.5px; letter-spacing: 0.02em; border: 1px solid var(--border); color: var(--muted); background: var(--surface); white-space: nowrap; }.pill.wl { color: var(--accent); border-color: #bfd8cb; background: var(--accent-soft); }.pill.early { color: var(--muted); border-color: var(--border); background: #f7faf8; }.pill.live { color: var(--faint); }.ticker { display: inline-flex; padding: 1px 6px; border-radius: 4px; background: #f4f7f5; border: 1px solid var(--line); font-size: 11px; color: var(--muted); }.pill.quiet { color: var(--faint); border-style: dashed; }.implied { display: flex; align-items: center; gap: 10px; }.bar { width: 92px; height: 5px; border-radius: 3px; background: #e6eee9; overflow: hidden; flex: none; }.bar i { display: block; height: 100%; background: var(--accent); }.empty { padding: 56px 24px; display: grid; gap: 12px; justify-items: center; text-align: center; }.button { height: 34px; padding: 0 14px; border: 1px solid var(--border); border-radius: 8px; background: var(--surface); font-size: 13px; }.button.primary { background: var(--accent); border-color: var(--accent); color: #fff; }.crumbs { display: flex; align-items: center; gap: 9px; margin-top: 14px; font-size: 12px; color: var(--faint); }.crumbs .sep { color: var(--border); }.crumb-rank { font-family: var(--font-num); font-size: 11.5px; color: var(--muted); }.link { border: 0; background: none; padding: 0; color: var(--accent); font-size: 12.5px; }.link:hover { text-decoration: underline; }.protocol-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 32px; margin-top: 6px; padding-bottom: 10px; }.protocol-title h1 { font-size: 32px; line-height: 1.1; }.protocol-title .sub { margin-top: 5px; font-family: var(--font-num); font-size: 12px; }.head-value { text-align: right; flex: none; }.head-label { display: block; font-size: 10.5px; letter-spacing: 0.06em; text-transform: uppercase; color: var(--faint); }.head-value b { display: block; font-family: var(--font-num); font-size: 30px; font-weight: 500; letter-spacing: -0.02em; line-height: 1.15; }.head-value em { display: block; font-style: normal; font-family: var(--font-num); font-size: 11.5px; color: var(--muted); }.head-value em.quiet { color: var(--faint); }.protocol-grid { display: grid; grid-template-columns: minmax(0, 1fr) 366px; gap: 20px; align-items: start; }.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 16px 20px 18px; }.card + .card { margin-top: 14px; }.card-head { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; margin-bottom: 8px; }.card-head h2 { font-size: 15px; letter-spacing: -0.01em; }.card-head .sub { font-family: var(--font-num); font-size: 11px; white-space: nowrap; }.plan-steps { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }.plan-steps li { display: grid; grid-template-columns: 24px minmax(0, 1fr); gap: 10px; padding-top: 6px; border-top: 1px solid var(--line); }.plan-steps li:first-child { border-top: 0; padding-top: 0; }.step-n { display: inline-flex; align-items: center; justify-content: center; width: 24px; height: 24px; border-radius: 50%; border: 1px solid var(--line); font-size: 11px; color: var(--muted); }.step-text { font-size: 13.5px; line-height: 1.4; }.chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 3px; }.chip { display: inline-flex; align-items: baseline; gap: 5px; padding: 1px 7px; border-radius: 5px; background: #f5f9f6; border: 1px solid var(--line); font-size: 11px; color: var(--muted); font-family: var(--font-num); }.chip-label { font-size: 9px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--faint); }.anchor { background: var(--accent-soft); border-radius: 10px; padding: 13px 16px 15px; }.anchor-label { display: block; font-size: 10px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent); }.anchor b { display: block; margin-top: 3px; font-family: var(--font-num); font-size: 30px; font-weight: 500; line-height: 1.1; letter-spacing: -0.02em; }.anchor p { margin-top: 9px; font-size: 11.5px; line-height: 1.48; color: var(--muted); }.anchor .sub { display: block; margin-top: 2px; font-size: 11px; }.foot { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--line); font-size: 11px; line-height: 1.5; color: var(--faint); }.waterfall { list-style: none; margin: 0; padding: 0; }.wf { display: grid; grid-template-columns: minmax(0, 1fr) 58px 78px; gap: 8px; align-items: baseline; padding: 4px 0; border-bottom: 1px dotted var(--line); }.wf:last-child { border-bottom: 0; }.wf-label { font-size: 12px; color: var(--muted); }.wf-mult { text-align: right; font-size: 11.5px; color: var(--faint); }.wf-value { text-align: right; font-size: 12.5px; font-weight: 500; }.wf-note { grid-column: 1 / -1; font-size: 10.5px; color: var(--faint); line-height: 1.35; margin-top: -3px; }.wf.total { border-top: 1px solid var(--border); border-bottom: 0; padding-top: 7px; margin-top: 3px; }.wf.total .wf-label { color: var(--ink); font-weight: 500; }.wf.total .wf-value { font-size: 14px; }.notes { margin: 0; padding: 0 0 0 15px; display: grid; gap: 7px; }.notes li { font-size: 12.5px; line-height: 1.48; color: var(--muted); }.method-head { padding: 18px 0 12px; }.method-head h1 { font-size: 30px; line-height: 1.15; }.method-head .lede-text { max-width: 76ch; }.formula-card { padding: 16px 24px 14px; }.formula-split { display: grid; grid-template-columns: minmax(0, 1.3fr) minmax(300px, 0.7fr); gap: 30px; align-items: start; }.formula { display: grid; gap: 8px; margin-bottom: 0; }.formula-line { font-family: var(--font-num); font-size: 13px; color: var(--muted); }.term { display: grid; grid-template-columns: 64px minmax(0, 1fr); column-gap: 12px; padding-left: 14px; border-left: 2px solid var(--accent-soft); }.term-name { font-family: var(--font-num); font-size: 11px; color: var(--accent); text-transform: uppercase; letter-spacing: 0.04em; align-self: center; }.term-body { font-family: var(--font-num); font-size: 12px; color: var(--ink); }.term-note { grid-column: 2; font-size: 10.5px; color: var(--faint); line-height: 1.4; }.caveats { margin-top: 14px; }.caveats .notes { grid-template-columns: 1fr 1fr; column-gap: 28px; }.method-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 18px; margin-top: 14px; }.method-grid .card + .card { margin-top: 0; }.coverage-line { margin-top: 12px; padding-top: 10px; border-top: 1px solid var(--line); font-size: 11px; line-height: 1.55; color: var(--faint); }
