  function ageStep(x) {
    if (x.age === null) {
      return {
        text: x.name + ' carries no first-listed date in the snapshot, so read its own launch post and audit before you commit: an untracked protocol is where an audit matters most.',
        cost: 'nothing but the reading',
        time: '20 minutes',
      };
